func (c *Reconciler) ReconcileKind(ctx context.Context, s *v1beta1.CloudAuditLogsSource) reconciler.Event {
	ctx = logging.WithLogger(ctx, c.Logger.With(zap.Any("auditlogsource", s)))

	s.Status.InitializeConditions()
