func (q *Query) Delete(ctx context.Context) error {
	if err := q.init(nil); err != nil {
		return err
	}
	if q.dq.Limit > 0 {
		return gcerr.Newf(gcerr.InvalidArgument, nil, "delete queries cannot have a limit")
	}
	return q.coll.driver.RunDeleteQuery(ctx, q.dq)
}

